def generate(omega, events):
    """The sigma-algebra on omega generated by events, as a set of frozensets."""
    whole = frozenset(omega)
    fam = {frozenset(), whole} | {frozenset(e) for e in events}
    while True:
        new = set(fam)
        for a in fam:
            new.add(whole - a)
            for b in fam:
                new.add(a | b)
        if new == fam:
            return fam
        fam = new

def is_sigma_algebra(omega, sets):
    """True when sets holds omega and is closed under complements and unions."""
    whole = frozenset(omega)
    fam = {frozenset(s) for s in sets}
    if whole not in fam:
        return False
    for a in fam:
        if whole - a not in fam:
            return False
        for b in fam:
            if a | b not in fam:
                return False
    return True
